import {shouldContinueToolLoop, sumUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('sumUsage', () => {
  it('adds every token field of two rounds that both reported usage', () => {
    const first: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};
    const second: UsageMetadata = {inputTokens: 7, outputTokens: 4, totalTokens: 11};

    expect(sumUsage(first, second)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('keeps the total unchanged when a round reported nothing', () => {
    const total: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};

    expect(sumUsage(total, undefined)).toEqual(total);
  });

  it('takes the round alone when no earlier round reported', () => {
    const next: UsageMetadata = {inputTokens: 7, outputTokens: 4, totalTokens: 11};

    expect(sumUsage(undefined, next)).toEqual(next);
  });

  it('stays undefined when no round reported at all', () => {
    expect(sumUsage(undefined, undefined)).toBeUndefined();
  });
});
